import{_ as t,a0 as d,w as p,s as r,ao as c,I as i,x as s,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"使用 rsync 复制大文件的一些误解 | LCTT x X-CMD","titleTemplate":false,"description":"使用 rsync 复制大文件的一些误解 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 rsync 复制大文件的一些误解 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 rsync 复制大文件的一些误解 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190916 Copying large files with Rsync, and some misconceptions","title":"使用 rsync 复制大文件的一些误解","tag":"201910","desc":""},"relativePath":"201910/20190916 Copying large files with Rsync, and some misconceptions.md","filePath":"[post].md"}'),l={name:"201910/20190916 Copying large files with Rsync, and some misconceptions.md"};function g(y,e,f,h,u,m){const n=d("Link");return p(),r("div",null,[e[15]||(e[15]=c(`<h1 id="使用-rsync-复制大文件的一些误解" tabindex="-1">使用 rsync 复制大文件的一些误解 <a class="header-anchor" href="#使用-rsync-复制大文件的一些误解" aria-label="Permalink to “使用 rsync 复制大文件的一些误解”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/08/rsync-816x345.jpg" alt=""></p><p>有一种观点认为，在 IT 行业工作的许多人经常从网络帖子里复制和粘贴。我们都干过，复制粘贴本身不是问题。问题是当我们在不理解它们的情况下这样干。</p><p>几年前，一个曾经在我团队中工作的朋友需要将虚拟机模板从站点 A 复制到站点 B。他们无法理解为什么复制的文件在站点 A 上为 10GB，但是在站点 B 上却变为 100GB。</p><p>这位朋友认为 <code>rsync</code> 是一个神奇的工具，应该仅“同步”文件本身。但是，我们大多数人所忘记的是了解 <code>rsync</code> 的真正含义、用法，以及我认为最重要的是它原本是用来做什么的。本文提供了有关 <code>rsync</code> 的更多信息，并解释了那件事中发生了什么。</p><h3 id="关于-rsync" tabindex="-1">关于 rsync <a class="header-anchor" href="#关于-rsync" aria-label="Permalink to “关于 rsync”">​</a></h3><p><code>rsync</code> 是由 Andrew Tridgell 和 Paul Mackerras 创建的工具，其动机是以下问题：</p><p>假设你有两个文件，<code>file_A</code> 和 <code>file_B</code>。你希望将 <code>file_B</code> 更新为与 <code>file_A</code> 相同。显而易见的方法是将 <code>file_A</code> 复制到 <code>file_B</code>。</p><p>现在，假设这两个文件位于通过慢速通信链接（例如，拨号 IP 链接）连接的两个不同的服务器上。如果<code>file_A</code> 大，将其复制到 <code>file_B</code> 将会很慢，有时甚至是不可能完成的。为了提高效率，你可以在发送前压缩 <code>file_A</code>，但这通常只会获得 2 到 4 倍的效率提升。</p><p>现在假设 <code>file_A</code> 和 <code>file_B</code> 非常相似，并且为了加快处理速度，你可以利用这种相似性。一种常见的方法是仅通过链接发送 <code>file_A</code> 和 <code>file_B</code> 之间的差异，然后使用这个差异列表在远程端重建文件。</p><p>问题在于，用于在两个文件之间创建一组差异的常规方法依赖于能够读取两个文件。因此，它们要求链接的一端预先提供两个文件。如果它们在同一台计算机上不是同时可用的，则无法使用这些算法。（一旦将文件复制过来，就不需要做对比差异了）。而这是 <code>rsync</code> 解决的问题。</p><p><code>rsync</code> 算法有效地计算源文件的哪些部分与现有目标文件的部分匹配。这样，匹配的部分就不需要通过链接发送了；所需要的只是对目标文件部分的引用。只有源文件中不匹配的部分才需要发送。</p><p>然后，接收者可以使用对现有目标文件各个部分的引用和原始素材来构造源文件的副本。</p><p>另外，可以使用一系列常用压缩算法中的任何一种来压缩发送到接收器的数据，以进一步提高速度。</p><p>我们都知道，<code>rsync</code> 算法以一种漂亮的方式解决了这个问题。</p><p>在 <code>rsync</code> 的介绍之后，回到那件事！</p><h3 id="问题-1-自动精简配置" tabindex="-1">问题 1：自动精简配置 <a class="header-anchor" href="#问题-1-自动精简配置" aria-label="Permalink to “问题 1：自动精简配置”">​</a></h3><p>有两件事可以帮助那个朋友了解正在发生的事情。</p><p>该文件在其他地方的大小变得越来越大的问题是由源系统上启用了<ruby>自动精简配置<rt>Thin Provisioning</rt></ruby>（TP）引起的，这是一种优化存储区域网络（SAN）或网络连接存储（NAS）中可用空间效率的方法。</p><p>由于启用了 TP，源文件只有 10GB，并且在不使用任何其他配置的情况下使用 <code>rsync</code> 进行传输时，目标位置将接收到全部 100GB 的大小。<code>rsync</code> 无法自动完成该（TP）操作，必须对其进行配置。</p><p>进行此工作的选项是 <code>-S</code>（或 <code>–sparse</code>），它告诉 <code>rsync</code> 有效地处理稀疏文件。它会按照它说的做！它只会发送该稀疏数据，因此源和目标将有一个 10GB 的文件。</p><h3 id="问题-2-更新文件" tabindex="-1">问题 2：更新文件 <a class="header-anchor" href="#问题-2-更新文件" aria-label="Permalink to “问题 2：更新文件”">​</a></h3><p>当发送一个更新的文件时会出现第二个问题。现在目标仅接收 10GB 了，但始终传输的是整个文件（包含虚拟磁盘），即使只是在该虚拟磁盘上更改了一个配置文件。换句话说，只是该文件的一小部分发生了更改。</p><p>用于此传输的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -avS vmdk_file syncuser@host1:/destination</span></span></code></pre></div><p>同样，了解 <code>rsync</code> 的工作方式也将有助于解决此问题。</p><p>上面是关于 <code>rsync</code> 的最大误解。我们许多人认为 <code>rsync</code> 只会发送文件的增量更新，并且只会自动更新需要更新的内容。<strong>但这不是 <code>rsync</code> 的默认行为</strong>。</p><p>如手册页所述，<code>rsync</code> 的默认行为是在目标位置创建文件的新副本，并在传输完成后将其移动到正确的位置。</p><p>要更改 <code>rsync</code> 的默认行为，你必须设置以下标志，然后 <code>rsync</code> 将仅发送增量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--inplace               原地更新目标文件</span></span>
<span class="line"><span>--partial               保留部分传输的文件</span></span>
<span class="line"><span>--append                附加数据到更短的文件</span></span>
<span class="line"><span>--progress              在传输时显示进度条</span></span></code></pre></div><p>因此，可以确切地执行我那个朋友想要的功能的完整命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -av --partial --inplace --append --progress vmdk_file syncuser@host1:/destination</span></span></code></pre></div><p>注意，出于两个原因，这里必须删除稀疏选项 <code>-S</code>。首先是通过网络发送文件时，不能同时使用 <code>–sparse</code> 和 <code>–inplace</code>。其次，当你以前使用过 <code>–sparse</code> 发送文件时，就无法再使用 <code>–inplace</code> 进行更新。请注意，低于 3.1.3 的 <code>rsync</code> 版本将拒绝 <code>–sparse</code> 和 <code>–inplace</code> 的组合。</p><p>因此，即使那个朋友最终通过网络复制了 100GB，那也只需发生一次。以下所有更新仅复制差异，从而使复制非常高效。</p><hr>`,35)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),o(n,{href:"https://fedoramagazine.org/copying-large-files-with-rsync-and-some-misconceptions/"},{default:a(()=>[...e[0]||(e[0]=[s("https://fedoramagazine.org/copying-large-files-with-rsync-and-some-misconceptions/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=s("作者：",-1)),o(n,{href:"https://fedoramagazine.org/author/dabreu/"},{default:a(()=>[...e[2]||(e[2]=[s("Daniel Leite de Abreu",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),o(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}cons